 num(E, 'Найдите значение $-2ab$ при $a = {{a}}$, $b = {{b}}$.', '-2 * a * b', '', 'Подставляем.', [C('a', [-3, 2, 5]), C('b', [-1, 4])]),
 ch(E, 'Чему равен коэффициент одночлена $-x^3$?', ['−1', '1', '3', '0'], 0, '$-x^3 = -1 \\cdot x^3$.'),
