 num(M, 'Объём куба с ребром ${{a}}a$ — одночлен. Найдите его коэффициент.', 'a^3', '', '$V = ({{a}}a)^3$.', [C('a', [2, 3])]),
 ch(M, 'Какой одночлен нужно поставить вместо ?, чтобы $(? )^2 = 25x^4y^2$?', ['$5x^2y$ (или $-5x^2y$)', '$25x^2y$', '$5x^4y^2$', '$5xy$'], 0, '$(5x^2y)^2 = 25x^4y^2$.'),
